using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using Object=UnityEngine.Object;
public static class GridShiftV11Setup {
 public static void Stage(){foreach(var path in new[]{"Assets/Scenes/SampleScene.unity","Assets/Scenes/Office.unity","Assets/Scenes/MainMenu.unity"}){var scene=EditorSceneManager.OpenScene(path);foreach(var route in Object.FindObjectsByType<TrafficRoute>(FindObjectsInactive.Include,FindObjectsSortMode.None))if(string.IsNullOrEmpty(route.stableId)){route.stableId=GridShiftRouteIdentity.Of(route);EditorUtility.SetDirty(route);}foreach(var component in Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(component==null)continue;string name=component.GetType().Name;if(name=="GridShiftUwbTerminal"){var so=new SerializedObject(component);var browser=so.FindProperty("browser");if(browser!=null)browser.objectReferenceValue=null;so.ApplyModifiedPropertiesWithoutUndo();component.enabled=false;EditorUtility.SetDirty(component);}if(name=="WebBrowserUIBasic")component.gameObject.SetActive(false);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}AssetDatabase.SaveAssets();Directory.CreateDirectory("Docs/Validacao11");File.WriteAllText("Docs/Validacao11/stage.txt","Interfaces nativas habilitadas; navegadores anteriores inativos; IDs de rotas serializados.\n");}
 public static void Batch(){Stage();EditorApplication.Exit(0);}
 public static void Cleanup(){Stage();foreach(var path in new[]{"Assets/Scenes/SampleScene.unity","Assets/Scenes/Office.unity","Assets/Scenes/MainMenu.unity"}){var scene=EditorSceneManager.OpenScene(path);foreach(var c in Object.FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include,FindObjectsSortMode.None)){if(c==null)continue;string name=c.GetType().Name;string ns=c.GetType().Namespace??"";if(ns.StartsWith("VoltstroStudios")||name.StartsWith("GridShiftUwb")||name.StartsWith("GridShiftBrowser")||name=="GridShiftDeliveryBridge"||name=="VuplexTerminalWebView")Object.DestroyImmediate(c);}foreach(var root in scene.GetRootGameObjects()){foreach(var t in root.GetComponentsInChildren<Transform>(true))if(t!=null&&(t.name=="BrowserViewport"||t.name=="BrowserNavigation"||t.name=="UrbanFlowPreparing"))Object.DestroyImmediate(t.gameObject);foreach(var t in root.GetComponentsInChildren<Transform>(true))GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);}EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}foreach(var path in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Generated"}).Select(AssetDatabase.GUIDToAssetPath)){var root=PrefabUtility.LoadPrefabContents(path);bool changed=false;foreach(var c in root.GetComponentsInChildren<MonoBehaviour>(true)){if(c==null)continue;string name=c.GetType().Name;string ns=c.GetType().Namespace??"";if(ns.StartsWith("VoltstroStudios")||name.StartsWith("GridShiftUwb")||name.StartsWith("GridShiftBrowser")||name=="GridShiftDeliveryBridge"){Object.DestroyImmediate(c);changed=true;}}if(changed)PrefabUtility.SaveAsPrefabAsset(root,path);PrefabUtility.UnloadPrefabContents(root);}var brand=GridShiftBranding.Current;if(brand!=null){var so=new SerializedObject(brand);var field=so.FindProperty("urbanFlow");if(field!=null){field.objectReferenceValue=null;so.ApplyModifiedPropertiesWithoutUndo();EditorUtility.SetDirty(brand);}}AssetDatabase.DeleteAsset("Assets/Generated/Terminal");AssetDatabase.DeleteAsset("Assets/Generated/Experience5/PortableBrowser.prefab");AssetDatabase.SaveAssets();File.WriteAllText("Docs/Validacao11/cleanup.txt","Componentes do navegador removidos das cenas e prefabs gerados.\n");}
 public static void CleanupBatch(){Cleanup();EditorApplication.Exit(0);}
}

